import { UseQueryResult, useQuery } from '@tanstack/react-query'
import { useMemo } from 'react'
import { useEthersProvider } from 'hooks/useEthersProvider'
import { useAccountMeta } from 'uniswap/src/contexts/UniswapContext'
import { UseQueryApiHelperHookArgs } from 'uniswap/src/data/apiClients/types'
import { CreateLPPositionRequest, CreateLPPositionResponse } from 'uniswap/src/data/tradingApi/__generated__'
import { isAbstractChain, getAbstractContracts } from 'uniswap/src/constants/abstractContracts'
import { UniverseChainId } from 'uniswap/src/features/chains/types'
import { ReactQueryCacheKey } from 'utilities/src/reactQuery/cache'
import { ethers } from 'ethers'
import { Token, Price } from '@uniswap/sdk-core'
import { encodeSqrtRatioX96, TickMath } from '@uniswap/v3-sdk'

// V2 Router ABI - only the functions we need
const V2_ROUTER_ABI = [
  {
    name: 'addLiquidity',
    type: 'function',
    stateMutability: 'nonpayable',
    inputs: [
      { name: 'tokenA', type: 'address' },
      { name: 'tokenB', type: 'address' },
      { name: 'stable', type: 'bool' },
      { name: 'amountADesired', type: 'uint256' },
      { name: 'amountBDesired', type: 'uint256' },
      { name: 'amountAMin', type: 'uint256' },
      { name: 'amountBMin', type: 'uint256' },
      { name: 'to', type: 'address' },
      { name: 'deadline', type: 'uint256' }
    ],
    outputs: [
      { name: 'amountA', type: 'uint256' },
      { name: 'amountB', type: 'uint256' },
      { name: 'liquidity', type: 'uint256' }
    ]
  },
  {
    name: 'addLiquidityETH',
    type: 'function',
    stateMutability: 'payable',
    inputs: [
      { name: 'token', type: 'address' },
      { name: 'stable', type: 'bool' },
      { name: 'amountTokenDesired', type: 'uint256' },
      { name: 'amountTokenMin', type: 'uint256' },
      { name: 'amountETHMin', type: 'uint256' },
      { name: 'to', type: 'address' },
      { name: 'deadline', type: 'uint256' }
    ],
    outputs: [
      { name: 'amountToken', type: 'uint256' },
      { name: 'amountETH', type: 'uint256' },
      { name: 'liquidity', type: 'uint256' }
    ]
  },
  {
    name: 'poolFor',
    type: 'function',
    stateMutability: 'view',
    inputs: [
      { name: 'tokenA', type: 'address' },
      { name: 'tokenB', type: 'address' },
      { name: 'stable', type: 'bool' },
      { name: '_factory', type: 'address' }
    ],
    outputs: [
      { name: 'pool', type: 'address' }
    ]
  },
  {
    name: 'quoteAddLiquidity',
    type: 'function',
    stateMutability: 'view',
    inputs: [
      { name: 'tokenA', type: 'address' },
      { name: 'tokenB', type: 'address' },
      { name: 'stable', type: 'bool' },
      { name: '_factory', type: 'address' },
      { name: 'amountADesired', type: 'uint256' },
      { name: 'amountBDesired', type: 'uint256' }
    ],
    outputs: [
      { name: 'amountA', type: 'uint256' },
      { name: 'amountB', type: 'uint256' },
      { name: 'liquidity', type: 'uint256' }
    ]
  }
] as const

// Abstract DEX V3 NFT Position Manager ABI - uses tickSpacing instead of fee
const V3_NFT_MANAGER_ABI = [
  {
    name: 'mint',
    type: 'function',
    stateMutability: 'payable',
    inputs: [
      {
        name: 'params',
        type: 'tuple',
        components: [
          { name: 'token0', type: 'address' },
          { name: 'token1', type: 'address' },
          { name: 'tickSpacing', type: 'int24' },
          { name: 'tickLower', type: 'int24' },
          { name: 'tickUpper', type: 'int24' },
          { name: 'amount0Desired', type: 'uint256' },
          { name: 'amount1Desired', type: 'uint256' },
          { name: 'amount0Min', type: 'uint256' },
          { name: 'amount1Min', type: 'uint256' },
          { name: 'recipient', type: 'address' },
          { name: 'deadline', type: 'uint256' },
          { name: 'sqrtPriceX96', type: 'uint160' }
        ]
      }
    ],
    outputs: [
      { name: 'tokenId', type: 'uint256' },
      { name: 'liquidity', type: 'uint128' },
      { name: 'amount0', type: 'uint256' },
      { name: 'amount1', type: 'uint256' }
    ]
  },
  {
    name: 'createAndInitializePoolIfNecessary',
    type: 'function',
    stateMutability: 'payable',
    inputs: [
      { name: 'token0', type: 'address' },
      { name: 'token1', type: 'address' },
      { name: 'tickSpacing', type: 'int24' },
      { name: 'sqrtPriceX96', type: 'uint160' }
    ],
    outputs: [
      { name: 'pool', type: 'address' }
    ]
  },
  {
    name: 'multicall',
    type: 'function',
    stateMutability: 'payable',
    inputs: [
      { name: 'data', type: 'bytes[]' }
    ],
    outputs: [
      { name: 'results', type: 'bytes[]' }
    ]
  }
] as const

interface AbstractLpCreationParams {
  token0?: string
  token1?: string
  amount0?: string
  amount1?: string
  chainId: UniverseChainId
  slippageTolerance?: number
  protocolVersion?: 'V2' | 'V3'
  // V2-specific parameters
  stable?: boolean // Pool type: stable vs volatile (V2 only)
  // V3-specific parameters
  fee?: number
  tickLower?: number
  tickUpper?: number
  sqrtPriceX96?: string
  createPool?: boolean
  tokenId?: string // For increase liquidity operations
}

export function useAbstractLpPositionCalldataQuery({
  params,
  deadlineInMinutes = 20,
  ...rest
}: UseQueryApiHelperHookArgs<CreateLPPositionRequest, CreateLPPositionResponse> & {
  deadlineInMinutes?: number
}): UseQueryResult<CreateLPPositionResponse> {
  const account = useAccountMeta()
  const address = account?.address

  // Extract Abstract-specific params from the request
  const abstractParams: AbstractLpCreationParams | null = useMemo(() => {
    if (!params) return null

    try {
      const chainId = params.chainId as UniverseChainId

      // Extract data from the actual structure
      const token0 = params.position?.pool?.token0
      const token1 = params.position?.pool?.token1

      // Detect protocol version based on position structure
      const fee = params.position?.pool?.fee
      const tickLower = params.position?.tickLower
      const tickUpper = params.position?.tickUpper
      const sqrtPriceX96 = params.initialPrice ? params.initialPrice : params.position?.pool?.sqrtRatioX96
      const createPool = params.createPool
      
      // Extract pool type (stable vs volatile) - check both top-level and nested locations
      const stable = (params as any).stable ?? (params.position?.pool as any)?.stable ?? false

      // Detect protocol version from explicit protocol field or position structure
      const protocolFromField = (params as any).protocol
      const protocolFromStructure = (fee !== undefined || tickLower !== undefined) ? 'V3' : 'V2'
      // If tokenId is present, this is a V3 increase liquidity operation
      const protocolFromTokenId = params.tokenId ? 'V3' : null
      const protocolVersion = protocolFromField || protocolFromTokenId || protocolFromStructure


      // Handle amounts based on independentToken
      let amount0, amount1
      const independentAmount = params.independentAmount
      const dependentAmount = params.defaultDependentAmount

      if (params.independentToken === 'TOKEN_0') {
        amount0 = independentAmount
        amount1 = dependentAmount
      } else if (params.independentToken === 'TOKEN_1') {
        amount0 = dependentAmount
        amount1 = independentAmount
      } else {
        // Fallback: assume TOKEN_0 is independent
        amount0 = independentAmount
        amount1 = dependentAmount
      }

      // If amounts are still missing, try direct properties
      if (!amount0 && params.amount0) amount0 = params.amount0
      if (!amount1 && params.amount1) amount1 = params.amount1

      const slippageTolerance = params.slippageTolerance || 0.5

      // Extract tokenId for increase liquidity operations
      const tokenId = params.tokenId

      return {
        chainId,
        token0,
        token1,
        amount0,
        amount1,
        slippageTolerance,
        protocolVersion,
        stable,
        fee,
        tickLower,
        tickUpper,
        sqrtPriceX96,
        createPool,
        tokenId,
      }
    } catch (error) {
      console.warn('Failed to parse Abstract LP creation params:', error)
      return null
    }
  }, [params])

  const contracts = getAbstractContracts(abstractParams?.chainId || UniverseChainId.Mainnet)
  const routerAddress = contracts?.router
  const poolFactoryAddress = contracts?.poolFactory
  const nftManagerAddress = contracts?.nonfungiblePositionManager
  const clFactoryAddress = contracts?.clFactory
  const provider = useEthersProvider({ chainId: abstractParams?.chainId || UniverseChainId.Mainnet })

  const queryKey = [ReactQueryCacheKey.AbstractLpApproval, 'lp-creation', abstractParams, address]



  return useQuery<CreateLPPositionResponse>({
    queryKey,
    queryFn: async () => {
      if (!abstractParams || !address || !provider) {
        throw new Error('Invalid parameters for Abstract LP creation')
      }

      if (abstractParams.protocolVersion === 'V2' && (!routerAddress || !poolFactoryAddress)) {
        throw new Error('Invalid V2 router/factory for Abstract LP creation')
      }

      if (abstractParams.protocolVersion === 'V3' && (!nftManagerAddress || !clFactoryAddress)) {
        throw new Error('Invalid V3 NFT manager/factory for Abstract LP creation')
      }

      if (!isAbstractChain(abstractParams.chainId)) {
        throw new Error('LP creation only supported on Abstract chains')
      }

      const { token0, token1, slippageTolerance = 0.5 } = abstractParams
      let { amount0, amount1 } = abstractParams

      if (!token0 || !token1 || !amount0 || !amount1) {
        throw new Error('Missing required token or amount parameters')
      }

      // Calculate deadline (current time + minutes)
      const deadline = Math.floor(Date.now() / 1000) + (deadlineInMinutes * 60)

      let normalizedSlippage = slippageTolerance
      if (normalizedSlippage > 1) {
        normalizedSlippage = normalizedSlippage / 100
      }
      if (normalizedSlippage < 0) {
        normalizedSlippage = 0
      }
      if (normalizedSlippage > 0.5) {
        throw new Error(`Invalid slippage tolerance: ${slippageTolerance}. Must be between 0% and 50%`)
      }
      const slippageBps = Math.floor(normalizedSlippage * 10000)
      const slippageMultiplierBps = 10000 - slippageBps

      const amount0BigInt = BigInt(amount0)
      const amount1BigInt = BigInt(amount1)
      let amountAMin = ((amount0BigInt * BigInt(slippageMultiplierBps)) / 10000n).toString()
      let amountBMin = ((amount1BigInt * BigInt(slippageMultiplierBps)) / 10000n).toString()

      // Handle V3 positions separately
      if (abstractParams.protocolVersion === 'V3') {
        // Check if this is increase liquidity (tokenId provided) or mint new position
        if (abstractParams.tokenId) {
          return await increaseV3Liquidity({
            abstractParams,
            address,
            nftManagerAddress: nftManagerAddress!,
            deadline,
            amount0,
            amount1,
            amountAMin,
            amountBMin,
            provider,
            slippageMultiplierBps
          })
        } else {
          return await createV3Position({
            abstractParams,
            address,
            nftManagerAddress: nftManagerAddress!,
            clFactoryAddress: clFactoryAddress!,
            deadline,
            amount0,
            amount1,
            amountAMin,
            amountBMin,
            provider,
            slippageMultiplierBps
          })
        }
      }

      // V2 Logic continues below...
      // Check if this involves native ETH (not WETH)
      // Native ETH is represented as 'ETH', 'NATIVE', or NATIVE_CHAIN_ID in the token addresses
      const ZERO_ADDRESS = '0x0000000000000000000000000000000000000000'
      const isETHPair = token0 === 'NATIVE' || token0.toLowerCase() === 'eth' || token0.toLowerCase() === 'native' || token0.toLowerCase() === ZERO_ADDRESS.toLowerCase() ||
                       token1 === 'NATIVE' || token1.toLowerCase() === 'eth' || token1.toLowerCase() === 'native' || token1.toLowerCase() === ZERO_ADDRESS.toLowerCase()

      try {
        // For pool operations, convert native ETH to WETH address
        const WETH_ADDRESS = getAbstractContracts(abstractParams.chainId)?.weth || '0x3439153EB7AF838Ad19d56E1571FBD09333C2809'
        const ZERO_ADDRESS = '0x0000000000000000000000000000000000000000'
        const poolToken0 = (token0 === 'NATIVE' || token0.toLowerCase() === 'eth' || token0.toLowerCase() === 'native' || token0.toLowerCase() === ZERO_ADDRESS.toLowerCase()) ? WETH_ADDRESS : token0
        const poolToken1 = (token1 === 'NATIVE' || token1.toLowerCase() === 'eth' || token1.toLowerCase() === 'native' || token1.toLowerCase() === ZERO_ADDRESS.toLowerCase()) ? WETH_ADDRESS : token1

        // Use user-specified amounts directly - no contract override

        let calldata: string
        let value = '0'

        if (isETHPair) {
          // addLiquidityETH - handle native ETH pairs
          const ZERO_ADDRESS = '0x0000000000000000000000000000000000000000'
          const isToken0ETH = token0 === 'NATIVE' || token0.toLowerCase() === 'eth' || token0.toLowerCase() === 'native' || token0.toLowerCase() === ZERO_ADDRESS.toLowerCase()
          const tokenAddress = isToken0ETH ? token1 : token0
          const tokenAmount = isToken0ETH ? amount1 : amount0
          const ethAmount = isToken0ETH ? amount0 : amount1
          const tokenMin = isToken0ETH ? amountBMin : amountAMin
          const ethMin = isToken0ETH ? amountAMin : amountBMin

          const routerInterface = new ethers.utils.Interface(V2_ROUTER_ABI)
          calldata = routerInterface.encodeFunctionData('addLiquidityETH', [
            tokenAddress,
            abstractParams.stable || false, // Use pool type from user selection
            tokenAmount,
            tokenMin,
            ethMin,
            address,
            deadline
          ])
          value = ethAmount
        } else {
          // addLiquidity


          const routerInterface = new ethers.utils.Interface(V2_ROUTER_ABI)
          calldata = routerInterface.encodeFunctionData('addLiquidity', [
            poolToken0,
            poolToken1,
            abstractParams.stable || false, // Use pool type from user selection
            amount0,
            amount1,
            amountAMin,
            amountBMin,
            address,
            deadline
          ])
        }

        const response: CreateLPPositionResponse = {
          create: {
            to: routerAddress,
            data: calldata,
            value,
            from: address,
            chainId: abstractParams.chainId,
          },
          gasFee: '100000000000000', // 100k gas * 1 gwei = 0.0001 ETH
          dependentAmount: undefined, // We'll calculate this if needed
        }

        // Try to simulate the transaction to get better error details
        try {
          await provider.estimateGas({
            to: routerAddress,
            data: calldata,
            value,
            from: address
          })

        } catch (gasError) {
          console.warn('V2 gas estimation failed:', gasError)
          // Continue anyway - let the UI handle the gas estimation
        }


        return response
      } catch (error) {
        throw error
      }
    },
    ...rest,
  })
}

// Import refactored services
import { PoolDetectionService } from './services/PoolDetectionService'
import { TokenProcessor } from './services/TokenProcessor'
import { TickProcessor } from './services/TickProcessor'
import { V3TransactionBuilder } from './builders/V3TransactionBuilder'
import { AbstractLpRequest } from './types/AbstractLpTypes'

type ExtendedCreateResponse = CreateLPPositionResponse & {
  simulatedAmounts?: {
    amount0: string
    amount1: string
  }
  minAmounts?: {
    amount0Min: string
    amount1Min: string
  }
}

// Helper function to create V3 positions (refactored)
async function createV3Position({
  abstractParams,
  address,
  nftManagerAddress,
  clFactoryAddress,
  deadline,
  amount0,
  amount1,
  amountAMin,
  amountBMin,
  provider,
  slippageMultiplierBps
}: {
  abstractParams: AbstractLpCreationParams
  address: string
  nftManagerAddress: string
  clFactoryAddress: string
  deadline: number
  amount0: string
  amount1: string
  amountAMin: string
  amountBMin: string
  provider: any
  slippageMultiplierBps: number
}): Promise<ExtendedCreateResponse> {
  const { token0, token1, fee, tickLower, tickUpper, sqrtPriceX96, createPool, chainId } = abstractParams

  // 1. Validate required parameters
  if (!fee || tickLower === undefined || tickUpper === undefined) {
    throw new Error('Missing V3 parameters: fee, tickLower, tickUpper')
  }

  // 2. Initialize services
  const tokenProcessor = new TokenProcessor()
  const tickProcessor = new TickProcessor()
  const poolDetectionService = new PoolDetectionService()
  const v3Builder = new V3TransactionBuilder()

  // 3. Process tokens and amounts
  const processedTokens = tokenProcessor.processTokensAndAmounts(
    token0!,
    token1!,
    amount0,
    amount1,
    chainId,
    abstractParams.slippageTolerance || 0.5
  )

  // 4. Convert fee to tick spacing and align ticks
  const tickSpacing = tokenProcessor.feeToTickSpacing(fee)
  const { alignedTickLower, alignedTickUpper } = tickProcessor.alignTicksToSpacing(
    tickLower,
    tickUpper,
    tickSpacing
  )

  // 5. Detect pool existence and current price
  const poolInfo = await poolDetectionService.getPoolInfo(
    processedTokens.finalToken0,
    processedTokens.finalToken1,
    tickSpacing,
    clFactoryAddress,
    provider
  )

  const mintSqrtPriceX96 = poolInfo.exists
    ? '0'
    : (sqrtPriceX96 || (await v3Builder.determineSqrtPriceX96(poolInfo, processedTokens, chainId, sqrtPriceX96)))

  const mintParamsBase = {
    token0: processedTokens.finalToken0,
    token1: processedTokens.finalToken1,
    tickSpacing,
    tickLower: alignedTickLower,
    tickUpper: alignedTickUpper,
    amount0Desired: processedTokens.finalAmount0,
    amount1Desired: processedTokens.finalAmount1,
    amount0Min: '0',
    amount1Min: '0',
    recipient: address,
    deadline,
    sqrtPriceX96: mintSqrtPriceX96,
  }

  const value = v3Builder.calculateEthValue(processedTokens)

  const MINT_ABI = [
    {
      name: 'mint',
      type: 'function',
      stateMutability: 'payable',
      inputs: [
        {
          name: 'params',
          type: 'tuple',
          components: [
            { name: 'token0', type: 'address' },
            { name: 'token1', type: 'address' },
            { name: 'tickSpacing', type: 'int24' },
            { name: 'tickLower', type: 'int24' },
            { name: 'tickUpper', type: 'int24' },
            { name: 'amount0Desired', type: 'uint256' },
            { name: 'amount1Desired', type: 'uint256' },
            { name: 'amount0Min', type: 'uint256' },
            { name: 'amount1Min', type: 'uint256' },
            { name: 'recipient', type: 'address' },
            { name: 'deadline', type: 'uint256' },
            { name: 'sqrtPriceX96', type: 'uint160' },
          ],
        },
      ],
      outputs: [
        { name: 'tokenId', type: 'uint256' },
        { name: 'liquidity', type: 'uint128' },
        { name: 'amount0', type: 'uint256' },
        { name: 'amount1', type: 'uint256' },
      ],
    },
  ]

  let amount0MinFinal = amountAMin
  let amount1MinFinal = amountBMin
  let simulatedAmounts: { amount0: string; amount1: string } | undefined

  if (provider) {
    try {
      const simulationContract = new ethers.Contract(nftManagerAddress, MINT_ABI, provider)
      const simulation = await simulationContract.callStatic.mint(mintParamsBase, {
        from: address,
        value: value === '0' ? undefined : ethers.BigNumber.from(value),
      })

      const simAmount0 = BigInt(simulation.amount0.toString())
      const simAmount1 = BigInt(simulation.amount1.toString())

      simulatedAmounts = {
        amount0: simAmount0.toString(),
        amount1: simAmount1.toString(),
      }

      amount0MinFinal = ((simAmount0 * BigInt(slippageMultiplierBps)) / 10000n).toString()
      amount1MinFinal = ((simAmount1 * BigInt(slippageMultiplierBps)) / 10000n).toString()
    } catch (error) {
      console.warn('[ABSTRACT_V3] mint simulation failed', error)
    }
  }

  const finalMintParams = {
    ...mintParamsBase,
    amount0Min: amount0MinFinal,
    amount1Min: amount1MinFinal,
  }

  const finalCalldata = v3Builder.buildMintCalldata(finalMintParams)

  let gasEstimate = '300000'
  if (provider?.estimateGas) {
    try {
      const gas = await provider.estimateGas({
        to: nftManagerAddress,
        data: finalCalldata,
        value,
        from: address,
      })
      gasEstimate = gas.toString()
    } catch (gasError) {
      console.warn('V3 gas estimation failed:', gasError)
    }
  }

  const response: ExtendedCreateResponse = {
    create: {
      to: nftManagerAddress,
      data: finalCalldata,
      value,
      from: address,
      chainId: abstractParams.chainId,
    },
    gasFeeCreate: ethers.BigNumber.from(gasEstimate).mul('1000000000').toString(),
    simulatedAmounts,
    minAmounts: {
      amount0Min: amount0MinFinal,
      amount1Min: amount1MinFinal,
    },
    sqrtRatioX96: poolInfo.sqrtPriceX96,
    currentTick: poolInfo.tick.toString(),
  }

  return response
}

// Helper function to increase liquidity on existing V3 positions
async function increaseV3Liquidity({
  abstractParams,
  address,
  nftManagerAddress,
  deadline,
  amount0,
  amount1,
  amountAMin,
  amountBMin,
  provider,
  slippageMultiplierBps
}: {
  abstractParams: AbstractLpCreationParams
  address: string
  nftManagerAddress: string
  deadline: number
  amount0: string
  amount1: string
  amountAMin: string
  amountBMin: string
  provider: any
  slippageMultiplierBps: number
}): Promise<ExtendedCreateResponse> {
  const { tokenId } = abstractParams

  if (!tokenId) {
    throw new Error('Missing tokenId for increase liquidity operation')
  }

  // Build increase liquidity parameters
  const increaseParams = {
    tokenId: tokenId.toString(),
    amount0Desired: amount0,
    amount1Desired: amount1,
    amount0Min: amountAMin,
    amount1Min: amountBMin,
    deadline
  }

  // Add increaseLiquidity ABI if not already present
  const INCREASE_LIQUIDITY_ABI = [
    {
      name: 'increaseLiquidity',
      type: 'function',
      stateMutability: 'payable',
      inputs: [
        {
          name: 'params',
          type: 'tuple',
          components: [
            { name: 'tokenId', type: 'uint256' },
            { name: 'amount0Desired', type: 'uint256' },
            { name: 'amount1Desired', type: 'uint256' },
            { name: 'amount0Min', type: 'uint256' },
            { name: 'amount1Min', type: 'uint256' },
            { name: 'deadline', type: 'uint256' }
          ]
        }
      ],
      outputs: [
        { name: 'liquidity', type: 'uint128' },
        { name: 'amount0', type: 'uint256' },
        { name: 'amount1', type: 'uint256' }
      ]
    }
  ]

  // Encode the increaseLiquidity function call
  const increaseInterface = new ethers.utils.Interface(INCREASE_LIQUIDITY_ABI)

  // Handle ETH value for native ETH positions
  let value = '0'
  const { token0, token1 } = abstractParams

  // Check if either token is native ETH and set appropriate value
  const isToken0ETH = token0 === 'NATIVE' || token0?.toLowerCase() === 'eth' || token0?.toLowerCase() === 'native' || token0?.toLowerCase() === '0x0000000000000000000000000000000000000000'
  const isToken1ETH = token1 === 'NATIVE' || token1?.toLowerCase() === 'eth' || token1?.toLowerCase() === 'native' || token1?.toLowerCase() === '0x0000000000000000000000000000000000000000'

  if (isToken0ETH || isToken1ETH) {
    // Send ETH value for the appropriate token amount
    const ethAmount = isToken0ETH ? amount0 : amount1
    value = ethAmount
  }

  let amount0MinFinal = amountAMin
  let amount1MinFinal = amountBMin
  let simulatedAmounts: { amount0: string; amount1: string } | undefined

  if (provider) {
    try {
      const simulationContract = new ethers.Contract(nftManagerAddress, INCREASE_LIQUIDITY_ABI, provider)
      const simulation = await simulationContract.callStatic.increaseLiquidity(
        {
          ...increaseParams,
          amount0Min: '0',
          amount1Min: '0',
        },
        {
          from: address,
          value: value === '0' ? undefined : ethers.BigNumber.from(value),
        },
      )

      const simAmount0 = BigInt(simulation.amount0.toString())
      const simAmount1 = BigInt(simulation.amount1.toString())

      simulatedAmounts = {
        amount0: simAmount0.toString(),
        amount1: simAmount1.toString(),
      }

      amount0MinFinal = ((simAmount0 * BigInt(slippageMultiplierBps)) / 10000n).toString()
      amount1MinFinal = ((simAmount1 * BigInt(slippageMultiplierBps)) / 10000n).toString()
    } catch (error) {
      console.warn('[ABSTRACT_V3] increaseLiquidity simulation failed', error)
    }
  }

  const finalIncreaseParams = {
    ...increaseParams,
    amount0Min: amount0MinFinal,
    amount1Min: amount1MinFinal,
  }

  const increaseCalldata = increaseInterface.encodeFunctionData('increaseLiquidity', [finalIncreaseParams])

  // Estimate gas for the transaction
  const gasEstimate = 300000 // Conservative estimate for increase liquidity

  const response: ExtendedCreateResponse = {
    create: {
      to: nftManagerAddress, // NFT Position Manager, not router
      data: increaseCalldata,
      value, // Send ETH if dealing with native ETH position
      from: address,
      chainId: abstractParams.chainId || 11124
    },
    gasFeeCreate: ethers.BigNumber.from(gasEstimate).mul('1000000000').toString(), // gas * 1 gwei
    simulatedAmounts,
    minAmounts: {
      amount0Min: amount0MinFinal,
      amount1Min: amount1MinFinal,
    },
  }

  return response
}
